// Foundational LO Codes (Balvatika/Class-1/Class-2) — sourced from NCF-FS Odisha
// framework generated by Gemini. Stored as per-class distinct rows:
//   id           → "BV3-PD-1.1.1"  (class-domain-code triple, unique globally)
//   code         → "PD 1.1.1"       (raw code as printed in the framework)
//   class        → 0 (BV3) | 1 (Class-1) | 2 (Class-2)
//   subject      → domain shorthand (PD/SED/CD/LLD/ACD/PLH) — used for lesson matching
//   description  → Odia LO text
//   competency   → Odia competency title (if present in HTML)
import foundational from './lo-codes-foundational.json'
export const FOUNDATIONAL_LO_CODES = foundational

// Domain → keywords used to auto-match a foundational LO code to a lesson period
// based on subject/book/chapter/period names.  Case-insensitive substring match.
export const DOMAIN_SUBJECT_KEYWORDS = {
  PD:  ['physical', 'motor', 'PE', 'sport', 'game', 'ଶାରୀରିକ', 'ମାଂସପେଶୀ', 'ଖେଳ', 'ବ୍ୟାୟାମ'],
  SED: ['value', 'social', 'ethical', 'emotional', 'moral', 'ନୈତିକ', 'ସାମାଜିକ', 'ଆବେଗ'],
  CD:  ['math', 'ଗଣିତ', 'science', 'ବିଜ୍ଞାନ', 'evs', 'cognitive', 'ବୌଦ୍ଧିକ', 'numeracy', 'ସଂଖ୍ୟା'],
  LLD: [
    // English + Odia language subjects
    'odia', 'ଓଡ଼ିଆ', 'english', 'ଇଂରାଜୀ', 'hindi', 'ହିନ୍ଦୀ', 'sanskrit', 'ସଂସ୍କୃତ',
    'language', 'literacy', 'ଭାଷା', 'ସାକ୍ଷରତା', 'reading', 'ପଠନ',
    // Jhulana / mother-tongue / environment-based language education (Foundational Odisha)
    'ଝୁଲଣା', 'jhulana', 'ମାତୃଭାଷା', 'matrubhasha', 'mother tongue',
    // "ପରିବେଶ ଭିତ୍ତିକ ଭାଷା ଶିକ୍ଷା" — environment-based LANGUAGE education, is LLD
    'ପରିବେଶ ଭିତ୍ତିକ ଭାଷା', 'ଭାଷା ଶିକ୍ଷା', 'ଭାଷା ବିକାଶ', 'ପାରିପାର୍ଶ୍ୱିକ ଭାଷା',
  ],
  ACD: ['art', 'କଳା', 'craft', 'music', 'ସଙ୍ଗୀତ', 'dance', 'ନାଚ', 'drawing', 'aesthetic', 'ସୌନ୍ଦର୍ଯ୍ୟ'],
  PLH: ['habit', 'behaviour', 'behavior', 'ଅଭ୍ୟାସ', 'ଶିକ୍ଷଣ', 'discipline'],
}

// Priority/precedence rule.  Some Odia subject names accidentally contain
// keywords for multiple domains (e.g. "ପରିବେଶ ଭିତ୍ତିକ ଭାଷା ଶିକ୍ଷା" contains
// both ପରିବେଶ (→ CD) and ଭାଷା (→ LLD)).  When the subject explicitly names a
// language-education flavour (ଭାଷା ଶିକ୍ଷା / ଭାଷା ବିକାଶ / ମାତୃଭାଷା / Jhulana),
// force it to LLD and drop the CD match.  Similar override for other pairs
// can be added below.
export function resolveMatchedDomains(hay) {
  const h = String(hay || '').toLowerCase()
  const matched = new Set()
  for (const [dom, kws] of Object.entries(DOMAIN_SUBJECT_KEYWORDS)) {
    if (kws.some(kw => h.includes(kw.toLowerCase()))) matched.add(dom)
  }
  // Language-first override: any explicit "language" flavour → LLD-only from
  // the {LLD, CD} pair.  Keep PD/SED/ACD/PLH matches intact so cross-subject
  // themes (e.g. "story time — value education") still work.
  const languageFlavour = /(ମାତୃଭାଷା|ଝୁଲଣା|matrubhasha|jhulana|ଭାଷା\s*ଶିକ୍ଷା|ଭାଷା\s*ବିକାଶ|ପରିବେଶ\s*ଭିତ୍ତିକ\s*ଭାଷା)/i.test(h)
  if (languageFlavour) {
    matched.delete('CD')
    matched.add('LLD')
  }
  return matched
}

// Given a lesson period's { subject, chapterName, periodName, className, bookName },
// return the set of foundational LO codes to APPEND (matching class + matching domain).
// STRATEGY (much more targeted than "all-codes-in-matched-domains"):
//   1. Determine which domains match the lesson's subject/chapter (usually 1, sometimes 2)
//   2. Within each matched domain, score every LO code by keyword overlap between the
//      code's `description` text and the lesson's haystack (title/topic/period/chapter)
//   3. Return only the TOP-N by score (default 4). If nothing scores >0, fall back to
//      the first 2 codes from the top competency family (broad safety-net).
//   4. Hard cap = 6 codes per lesson period.
export function pickMatchingFoundationalCodes({ classCode, haystack, maxCodes = 4 }) {
  const hay = (haystack || '').toLowerCase()
  if (!hay || !classCode) return []
  // Use language-first-priority resolver so mixed-keyword subjects (e.g.
  // "ପରିବେଶ ଭିତ୍ତିକ ଭାଷା ଶିକ୍ଷା") don't over-match into the CD (math/science) domain.
  const matchedDomains = resolveMatchedDomains(hay)
  if (matchedDomains.size === 0) return []
  // Fetch classCode's codes in matched domain(s) only
  const pool = foundational.filter(o => o.classCode === classCode && matchedDomains.has(o.domain))
  if (pool.length === 0) return []
  // Extract meaningful tokens from the haystack (>= 3 chars, Odia included).
  // Skip common Odia stop-words / postpositions that would over-match.
  const STOP = new Set(['ଓ','କୁ','ର','ରେ','କୁ','ଏବଂ','ଏକ','ଏକ‌ଥର','ଆଉ','ମଧ୍ୟ','ପାଇଁ','ଏହା','ଏହି','ଏହାର','ସ','ଏ','ଏକ‌ଥର','ର','ମ','ଙ୍କ','the','and','of','to','in','a','an','is','are','for','on','with','as'])
  const tokens = hay
    .split(/[\s,।.:;()\-\/\\\d]+/)
    .map(t => t.trim().toLowerCase())
    .filter(t => t.length >= 3 && !STOP.has(t))
  const tokenSet = new Set(tokens)
  // Score each code by how many haystack tokens appear in its description
  const scored = pool.map(o => {
    const text = (o.description || '').toLowerCase()
    let score = 0
    for (const t of tokenSet) {
      if (t && text.includes(t)) score++
    }
    return { code: o, score }
  })
  scored.sort((a, b) => b.score - a.score)
  const top = scored.filter(s => s.score > 0).slice(0, maxCodes).map(s => s.code)
  if (top.length > 0) return top
  // Safety-net fallback: if nothing scored, take the first 2 codes from each
  // matched domain (broadly representative). This keeps the alignment from
  // producing empty results for out-of-vocabulary lesson names.
  const fallback = []
  for (const dom of matchedDomains) {
    const domCodes = pool.filter(o => o.domain === dom).slice(0, 2)
    fallback.push(...domCodes)
    if (fallback.length >= maxCodes) break
  }
  return fallback.slice(0, maxCodes)
}

// Map an app "class" name → our foundational classCode (BV3 / C1 / C2). Returns null
// if the class is outside the Balvatika-Class-2 range.
export function classNameToFoundationalCode(name) {
  const s = String(name || '').toLowerCase().replace(/\s+/g, '')
  if (/balvatika|sishuvatika|ଶିଶୁ|ବାଲ୍ୟ|balbat|balbot|balvat/.test(s)) return 'BV3'
  if (/^class[-]?1$|^grade[-]?1$|prathama|1stclass|ପ୍ରଥମ/.test(s)) return 'C1'
  if (/^class[-]?2$|^grade[-]?2$|dwitiya|dvitiya|2ndclass|ଦ୍ୱିତୀୟ|ଦ୍ଵିତୀୟ/.test(s)) return 'C2'
  // Also allow purely numeric labels
  if (/^0$|^bv/i.test(s)) return 'BV3'
  if (/^1$/.test(s)) return 'C1'
  if (/^2$/.test(s)) return 'C2'
  return null
}
